import styled, { css } from "styled-components";
import { BasicButton } from "../shared/input-wrapper";
import { lineClampCss } from "../shared/styles";
import {
    Border,
    Colour,
    Font,
    Motion,
    Radius,
    Shadow,
    Spacing,
} from "../theme";
import { Typography } from "../typography";

// =============================================================================
// STYLE INTERFACE, transient props are denoted with $
// See more https://styled-components.com/docs/api#transient-props
// =============================================================================
interface TableWrapperProps {
    $scrollable: boolean;
}
interface TableHeadProps {
    $stickyHeader: boolean | undefined;
}
interface HeaderCellProps {
    $clickable: boolean;
    $isCheckbox: boolean;
}
interface BodyRowProps {
    $alternating: boolean;
    $isSelected?: boolean;
    $isSelectable?: boolean;
    $showLastRowBottomBorder?: boolean;
}

interface BodyCellProps {
    $isCheckbox: boolean;
}

interface ActionBarWrapperProps {
    $strategy: "fixed" | "sticky" | "inline";
    $left?: number | undefined;
    $width?: number | undefined;
}

interface ActionBarProps {
    $float: boolean;
}

// =============================================================================
// STYLES CONSTANTS
// =============================================================================
const borderColor = Colour["border"];
const fontColor = Colour["text"];

// =============================================================================
// STYLES
// =============================================================================
export const TableWrapper = styled.div<TableWrapperProps>`
    /* we separate the overflow styles so that sticky elements can still work
       with horizontal scrolling on supported browsers
       see: https://github.com/w3c/csswg-drafts/issues/12289 */
    overflow-y: ${(props) => (props.$scrollable ? "auto" : "clip")};
    overflow-x: auto;
    position: relative;
    display: flex;
    flex-direction: column;
    border: ${Border["width-010"]} ${Border["solid"]} ${borderColor};
    border-radius: ${Radius["md"]};

    /* Hide scrollbar */
    scrollbar-width: none; /* Firefox */
    -ms-overflow-style: none; /* IE 10+ */
    &::-webkit-scrollbar {
        display: none; /* Chrome/Safari/Webkit */
    }
`;

export const TableContainer = styled.div`
    flex: 1;
`;

export const Table = styled.table`
    th:last-child,
    td:last-child {
        padding-right: 1.5rem;
    }
    th:first-child,
    td:first-child {
        padding-left: 1.5rem;
    }
    text-align: left;
    border-collapse: separate;
    border-spacing: 0;
    width: 100%;
`;

export const TableHead = styled.thead<TableHeadProps>`
    ${(props) => {
        if (props.$stickyHeader) {
            return css`
                position: sticky;
                top: 0;
                z-index: 20;
            `;
        }
    }};
`;

export const TableBody = styled.tbody``;

export const ActionBarWrapper = styled.div<ActionBarWrapperProps>`
    ${(props) => {
        const left = props.$left ? `${props.$left}px` : "0";
        const width = props.$width ? `${props.$width}px` : "100%";

        switch (props.$strategy) {
            case "inline":
                return css`
                    position: absolute;
                    bottom: 0;
                    left: 0;
                    width: ${width};
                `;
            case "fixed":
                return css`
                    position: fixed;
                    bottom: 0;
                    left: ${left};
                    width: ${width};
                `;
            case "sticky":
                return css`
                    position: sticky;
                    bottom: 0;
                    width: ${width};
                `;
        }
    }}
`;

export const TextButton = styled(BasicButton)`
    ${Font["body-md-semibold"]}
    cursor: pointer;
    color: ${Colour["text-primary"]};
    transition: ${Motion["duration-150"]} ${Motion["ease-default"]};
    padding: 0.75rem;
    margin: -0.75rem 0;

    &:hover {
        color: ${Colour["text-hover"]};
    }
`;

export const ActionBar = styled.div<ActionBarProps>`
    overflow: hidden;
    display: flex;
    align-items: center;
    height: 3.5rem;
    padding: ${Spacing["spacing-16"]} ${Spacing["spacing-24"]};
    border-top: ${Border["width-010"]} ${Border["solid"]} ${borderColor};
    background-color: ${Colour["bg-selected"]};
    transition: transform ${Motion["duration-350"]} ${Motion["ease-default"]};
    ${(props) => {
        if (props.$float) {
            return css`
                transform: translateX(0.5rem) translateY(-2rem);
                border-radius: ${Radius["sm"]};
                box-shadow: ${Shadow["xs-subtle"]};
                width: calc(100% - ${Spacing["spacing-16"]});
                border: ${Border["width-010"]} ${Border["solid"]} ${borderColor};
            `;
        } else {
            return css`
                border-radius: ${Radius["none"]} ${Radius["none"]}
                    ${Radius["sm"]} ${Radius["sm"]};
            `;
        }
    }}
`;

export const ActionBarGap = styled.div`
    width: 0.75rem;
`;

export const ActionBarSpacer = styled.div`
    height: 3.5rem;
`;

export const HeaderRow = styled.tr`
    background-color: ${Colour["bg-stronger"]};
    height: 6rem;
    border-bottom: ${Border["width-010"]} ${Border["solid"]} ${borderColor};
`;

export const HeaderCell = styled.th<HeaderCellProps>`
    padding: ${(props) =>
        props.$isCheckbox ? "1.25rem 0.5rem 1.25rem 1.5rem" : "1.25rem 1rem"};
    text-align: left;
    cursor: ${(props) => (props.$clickable ? "pointer" : "default")};
    vertical-align: middle;
    color: ${fontColor};
    border-bottom: ${Border["width-010"]} ${Border["solid"]} ${borderColor};
    ${(props) => {
        if (props.$isCheckbox) {
            return css`
                width: 4rem;
            `;
        }
    }};
    &:focus-within {
        outline: 2px solid ${Colour["focus-ring"]};
        outline-offset: -3px;
    }
`;

export const HeaderCellWrapper = styled.div`
    display: flex;
    flex-direction: row;
    align-items: center;

    svg {
        color: ${fontColor};
        margin-left: 0.5rem;
    }
`;

export const BodyRow = styled.tr<BodyRowProps>`
    background-color: ${(props) => {
        if (props.$isSelected) {
            return css`
                ${Colour["bg-selected"]};
            `;
        } else if (props.$alternating) {
            return css`
                ${Colour["bg-strong"]};
            `;
        } else {
            return css`
                ${Colour["bg"]};
            `;
        }
    }};
    border-top: ${Border["width-010"]} ${Border["solid"]} ${borderColor};
    &:hover {
        ${(props) => {
            if (props.$isSelectable) {
                return css`
                    background-color: ${Colour["bg-hover-strong"]};
                `;
            }
        }};
    }

    &:last-child {
        td {
            border-bottom: ${(props) =>
                props.$showLastRowBottomBorder
                    ? `${Border["width-010"]} ${Border["solid"]} ${borderColor}`
                    : "none"};
        }
    }
`;

export const BodyCell = styled.td<BodyCellProps>`
    padding: ${(props) =>
        props.$isCheckbox ? "1.25rem 0.5rem 1.25rem 1.5rem" : "1.25rem 1rem"};
    vertical-align: middle;
    color: ${fontColor};
    border-bottom: ${Border["width-010"]} ${Border["solid"]} ${borderColor};
`;

export const BodyCellContent = styled(Typography.BodyBL)`
    ${lineClampCss(2)}
    text-overflow: ellipsis;
`;

export const CheckBoxWrapper = styled.div`
    display: flex;
    align-items: center;
    justify-content: center;
`;

export const LoaderWrapper = styled.div`
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: 4rem 0;
`;

export const ErrorDisplayTitle = styled(Typography.HeadingSM)`
    margin-top: 2rem;
    margin-bottom: 1rem;
`;

export const EmptyViewCell = styled.td`
    padding: 4rem 0;
`;
